import java.time.LocalDate;
import java.time.format.DateTimeFormatter;

public class Main {
    public static void main(String[] args) {
        DateTimeFormatter 斜杠念法 = DateTimeFormatter.ofPattern("yyyy/MM/dd");

        LocalDate d = LocalDate.parse("2026/{m1}/{d1}", 斜杠念法);

        System.out.println("念出来了：" + d);
        System.out.println("餐券上写：" + d.format(DateTimeFormatter.ofPattern("yyyy年MM月dd日")));
    }
}
